// MARK: - DailyDrop (daily_drops)

/// The Daily Drop: one drop a day at 16:00 UTC with real inventory. spots_left is always a true count; claims are 24-hour reserved places to submit. Unclaimed spots return to the open feed.
struct DailyDrop: Codable, Hashable, Identifiable, Sendable {
    /// drop_<YYYY-MM-DD>.
    var id: String
    var date: String
    /// The date at 16:00:00Z.
    var releaseAt: Date
    /// release_at + 24 hours.
    var claimWindowEndsAt: Date
    /// upcoming before release_at, live after, sold_out when every spot is claimed, closed after the claim window.
    var status: DropStatus
    /// e.g. "Six new bounties. Real spots."
    var headline: String
    /// Bounties released through the drop (visibility drop or open).
    var items: [DropItem]
    /// Sum of items.spots_total.
    var spotsTotal: Int
    /// Sum of items.spots_left (a true count).
    var spotsLeft: Int
    /// spots_total - spots_left.
    var claimsTotal: Int
    var createdAt: Date
}

