// MARK: - Streak (streaks)

/// A creator's weekly posting streak. A week counts when the creator posts at least once in the ISO week (Monday to Sunday UTC). Earned freezes (1 per 4-week streak, max 2 banked), declared rest weeks, no inactivity penalty, no guilt copy.
struct Streak: Codable, Hashable, Identifiable, Sendable {
    /// stk_<creator slug>.
    var id: String
    var creatorId: String
    var status: StreakStatus
    /// Equals creators.streak_weeks.
    var currentWeeks: Int
    var bestWeeks: Int
    /// 0 to 2.
    var freezesBanked: Int
    var freezesEarnedTotal: Int
    var freezesUsedTotal: Int
    /// At most 2 per quarter.
    var restWeeksUsedQuarter: Int
    /// The current ISO week, e.g. "2026-W40".
    var isoWeek: String
    var postsThisWeek: Int
    var postedThisWeek: Bool
    /// Sunday 23:59:59Z of the current ISO week.
    var weekEndsAt: Date
    /// Weeks of streak until the next freeze is earned (0 to 3).
    var nextFreezeInWeeks: Int
    /// The last 12 ISO weeks, oldest first.
    var history: [WeekRecord]
    var updatedAt: Date
}

